-- Preserve dependent records while replacing the EU-only table constraints.
PRAGMA defer_foreign_keys = ON;
CREATE TABLE region_backup_squad_characters AS SELECT * FROM squad_characters;
CREATE TABLE region_backup_wishlist_entries AS SELECT * FROM wishlist_entries;
CREATE TABLE region_backup_character_sections AS SELECT * FROM character_sections;
CREATE TABLE region_backup_availability_entries AS SELECT * FROM availability_entries;
DROP TRIGGER membership_ruleset;
CREATE TABLE squads_regions (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL DEFAULT 'eu' CHECK(region IN ('eu','us','kr','tw','cn')), ruleset TEXT NOT NULL CHECK(ruleset IN ('normal','pvp','roleplay')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO squads_regions SELECT * FROM squads;
DROP TABLE squads;
ALTER TABLE squads_regions RENAME TO squads;
CREATE TABLE characters_regions (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL, region TEXT NOT NULL DEFAULT 'eu' CHECK(region IN ('eu','us','kr','tw','cn')), ruleset TEXT NOT NULL CHECK(ruleset IN ('normal','pvp','roleplay')), owner_id TEXT REFERENCES users(id) ON DELETE SET NULL, verified INTEGER NOT NULL DEFAULT 0, provider TEXT, external_id TEXT, profile_json TEXT NOT NULL DEFAULT '{}', sync_status TEXT NOT NULL DEFAULT 'idle', sync_error TEXT, last_synced_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, next_due INTEGER, lease_until INTEGER, lease_token TEXT, failure_count INTEGER NOT NULL DEFAULT 0, CHECK(verified=0 OR (provider IS NOT NULL AND external_id IS NOT NULL)));
INSERT INTO characters_regions SELECT * FROM characters;
DROP TABLE characters;
ALTER TABLE characters_regions RENAME TO characters;
CREATE UNIQUE INDEX placeholder_identity ON characters(region,ruleset,normalized_name) WHERE verified=0;
CREATE UNIQUE INDEX verified_identity ON characters(provider,region,ruleset,external_id) WHERE verified=1;
CREATE TRIGGER character_limit BEFORE INSERT ON characters WHEN (SELECT COUNT(*) FROM characters)>=50 BEGIN SELECT RAISE(ABORT,'Maximum of 50 stored characters reached'); END;
CREATE TRIGGER membership_ruleset BEFORE INSERT ON squad_characters WHEN (SELECT ruleset FROM squads WHERE id=NEW.squad_id)!=(SELECT ruleset FROM characters WHERE id=NEW.character_id) BEGIN SELECT RAISE(ABORT,'Character and squad rulesets must match'); END;
CREATE INDEX refresh_due ON characters(next_due) WHERE verified=1;
CREATE TRIGGER membership_region BEFORE INSERT ON squad_characters WHEN (SELECT region FROM squads WHERE id=NEW.squad_id)!=(SELECT region FROM characters WHERE id=NEW.character_id) BEGIN SELECT RAISE(ABORT,'Character and squad regions must match'); END;
INSERT INTO squad_characters SELECT * FROM region_backup_squad_characters;
DROP TABLE region_backup_squad_characters;
INSERT INTO wishlist_entries SELECT * FROM region_backup_wishlist_entries;
DROP TABLE region_backup_wishlist_entries;
INSERT INTO character_sections SELECT * FROM region_backup_character_sections;
DROP TABLE region_backup_character_sections;
INSERT INTO availability_entries SELECT * FROM region_backup_availability_entries;
DROP TABLE region_backup_availability_entries;
PRAGMA defer_foreign_keys = OFF;
